i = i.rstrip() + '\n240. **THE SAMPLE**\n'
write(INDEX, i)

w = read(WORKFLOW)
w = replace_once(w, 'Chapter 239 — **THE WAITER**.', 'Chapter 240 — **THE SAMPLE**.', 'WORKFLOW current edge')
w = replace_once(w, 'Chapter 240 edge.', 'Chapter 241 edge.', 'WORKFLOW next edge')
write(WORKFLOW, w)

p = read(PROJECT)
p = replace_once(p, 'Current recorded story endpoint is Chapter 239 — **THE WAITER**.', 'Current recorded story endpoint is Chapter 240 — **THE SAMPLE**.', 'PROJECT endpoint')
write(PROJECT, p)

m2 = read(MANUSCRIPT)
ch = m2.split('# CHAPTER 240', 1)[1]
if '# CHAPTER 241' in ch:
    raise SystemExit('Unexpected Chapter 241 found')
words = len(re.findall(r"\b\w[\w'’-]*\b", ch))
emdashes = ch.count('—')
print(f'CH240_WORDS={words}')
print(f'CH240_EMDASHES={emdashes}')
if words < 2500 or words > 4000:
    raise SystemExit(f'Chapter 240 word count out of range: {words}')
if emdashes != 0:
    raise SystemExit(f'Chapter 240 contains em dash characters: {emdashes}')

checks = {
    'state_endpoint': 'Chapter 240 — **THE SAMPLE**' in read(STATE),
    'state_counts': all(x in read(STATE) for x in ['35 successful supervised minimal draws', '31 supervised deliberate shaping attempts', '53 supervised external-effect attempts']),
    'state_attempt52': 'Attempt 52 FAR/AWAY: small observed target response' in read(STATE),
    'open_endpoint': 'Chapter 240 — **THE SAMPLE**' in read(OPEN),
    'open_counts': '35 supervised minimal draws / 31 deliberate shaping attempts / 53 external-effect attempts' in read(OPEN),
    'index_header': '# PEG-LEG GREG — CHAPTER INDEX — CH240' in read(INDEX),
    'index_endpoint': '**Current endpoint:** Chapter 240 — THE SAMPLE' in read(INDEX),
    'index_tail': read(INDEX).rstrip().endswith('240. **THE SAMPLE**'),
    'workflow_current': 'Chapter 240 — **THE SAMPLE**.' in read(WORKFLOW),
    'workflow_next': 'Chapter 241 edge.' in read(WORKFLOW),
    'project': 'Current recorded story endpoint is Chapter 240 — **THE SAMPLE**.' in read(PROJECT),
    'restrictions': 'Restrictions unchanged: no independent draw, shaping, external testing, paper, coins, thread, larger objects, practice, Barrier broadening, theatrical magic, or loopholes.' in read(STATE),
    'vale_bren': 'No Vale/Bren connection established.' in read(STATE),
}
for name, ok in checks.items():
    print(f'CHECK_{name}={"OK" if ok else "FAIL"}')
    if not ok:
        raise SystemExit(f'Verification failed: {name}')
